INSERT INTO public.courses (id, title, description, requirements) VALUES ('calculus-1', '高等数学（上）', '同济大学《高等数学》第六版上册，涵盖函数与极限、导数与微分、微分中值定理、不定积分、定积分及其应用、微分方程。', '["完成每个理论小节配套的即时训练题","完成每个模块末尾的综合练习","完成每个模块末尾的测验"]'::jsonb) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, requirements = EXCLUDED.requirements;
INSERT INTO public.courses (id, title, description, requirements) VALUES ('calculus-2', '高等数学（下）', '同济大学《高等数学》第六版下册，涵盖空间解析几何与向量代数、多元函数微分法、重积分、曲线积分与曲面积分、无穷级数。', '["完成每个理论小节配套的即时训练题","完成每个模块末尾的综合练习","完成每个模块末尾的测验"]'::jsonb) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, requirements = EXCLUDED.requirements;
INSERT INTO public.courses (id, title, description, requirements) VALUES ('physics-b-1', '大学物理B（上）', '长沙理工大学大学物理B（上），涵盖质点力学、刚体转动、机械振动与波动、波动光学等核心内容，通过章节理论与期末综合测验巩固物理思维能力。', '["完成各章节理论学习","完成力学期末综合测验","完成波动光学期末综合测验"]'::jsonb) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, requirements = EXCLUDED.requirements;
